import React, { useState } from 'react';
import axios from 'axios';
import './BikePage.css';

const BikePage = () => {
  // Cities and images
  const cityData = {
    "Yamunanagar": "https://d3sftlgbtusmnv.cloudfront.net/blog/wp-content/uploads/2024/10/Chaneti-Stupa.jpg",
    "Kurukshetra": "https://thumbs.dreamstime.com/b/sarveshwar-mahadev-temple-brahma-sarovar-kurukshetra-sarveshwar-mahadev-temple-located-brahma-sarovar-kurukshetra-india-428706026.jpg",
    "Chandigarh": "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/09/4c/43/64/the-rock-garden-of-chandigarh.jpg?w=900&h=500&s=1",
    "Karnal": "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/04/7a/f4/f0/noor-mahal.jpg?w=1400&h=1400&s=1",
    "Ambala": "https://static.where-e.com/India/Gurudwara-Panjokhra-Sahib_4a681ef6e540a5634542a6af91fda8e1.jpg",
    "Panchkula": "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/04/58/ae/62/morni-hills.jpg?w=1200&h=-1&s=1"
  };

  // State Management
  const [selectedCity, setSelectedCity] = useState("Yamunanagar");
  const [pickup, setPickup] = useState("");
  const [drop, setDrop] = useState("");
  const [mobile, setMobile] = useState("");
  const [fare, setFare] = useState(null);
  const [loading, setLoading] = useState(false);

  const vehicles = [
    { id: 1, name: '2 Wheeler', cap: '20kg', price: '20', img: 'https://nest-platform-assets.porter.in/2_wheeler_5624a12e03_cd20b2a174.svg' }, 
  ];

  const routes = [
    { to: "Karnal", kms: "80 Kms", price: "1600" },
    { to: "Ambala", kms: "55 Kms", price: "1100" },
    { to: "Chandigarh", kms: "95 Kms", price: "1900" }
  ];

  // Logic to fetch fare from Backend
  const handleGetFare = async () => {
    if (!pickup || !drop) {
      alert("Please enter both Pickup and Drop locations");
      return;
    }

    setLoading(true);
    try {
      // Backend API call (Make sure your Spring Boot is running)
      const response = await axios.get(`http://localhost:8080/api/get-fare`, {
        params: { 
          from: pickup, 
          to: drop 
        }
      });
      
      // Backend se jo fare aayega usey set karenge
      setFare(response.data.fare);
    } catch (error) {
      console.error("Error fetching fare:", error);
      alert("Could not fetch fare. Please check API key or locations.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="booking-wrapper">
      <section 
        className="hero-section" 
        style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.6), rgba(15, 23, 42, 0.6)), url(${cityData[selectedCity]})` }}
      >
        <div className="city-selector-top">
           <span className="location-icon">📍</span>
           <select value={selectedCity} onChange={(e) => setSelectedCity(e.target.value)}>
            {Object.keys(cityData).map(city => (
              <option key={city} value={city}>{city}</option>
            ))}
          </select>
        </div>

        {/* Dynamic Fare Card - Sirf tab dikhega jab fare mil jaye */}
        {fare && (
          <div className="fare-result-card slide-up" style={{
            background: 'white', padding: '20px', borderRadius: '15px', 
            position: 'absolute', top: '20%', left: '50%', transform: 'translateX(-50%)',
            boxShadow: '0 10px 25px rgba(0,0,0,0.2)', textAlign: 'center', minWidth: '250px', zIndex: 10
          }}>
            <p style={{ color: '#64748b', margin: 0, fontWeight: '600' }}>TOTAL ESTIMATED BIKE FARE</p>
            <h2 style={{ fontSize: '2.5rem', color: '#2563eb', margin: '10px 0' }}>₹{fare}</h2>
            <p style={{ fontSize: '0.8rem', color: '#94a3b8' }}>*Final price may vary based on traffic</p>
          </div>
        )}

        <div className="hero-text-center">
            <h1>Two Wheeler Booking in <span className="highlight">{selectedCity}</span></h1>
            <p>Affordable. Reliable. Professional at ₹20/km.</p>
        </div>

        <div className="booking-bar-white">
          <div className="form-input">
            <label>Pickup Point *</label>
            <input 
              type="text" 
              placeholder="Ex: Model Town" 
              value={pickup}
              onChange={(e) => setPickup(e.target.value)}
            />
          </div>
          <div className="form-input">
            <label>Drop Location *</label>
            <input 
              type="text" 
              placeholder="Ex: ISBT Delhi" 
              value={drop}
              onChange={(e) => setDrop(e.target.value)}
            />
          </div>
          <div className="form-input">
            <label>Mobile Number *</label>
            <input 
              type="tel" 
              placeholder="+91 XXXXX XXXXX" 
              value={mobile}
              onChange={(e) => setMobile(e.target.value)}
            />
          </div>
          <button 
            className="fare-estimate-btn" 
            onClick={handleGetFare}
            disabled={loading}
          >
            {loading ? "Calculating..." : "Get Fare Estimate"} <span className="arrow-icon">→</span>
          </button>
        </div>
      </section>

      <section className="vehicle-selection-area">
        <h2 className="section-title">Available 2 Wheelers in {selectedCity}</h2>
        <div className="vehicle-cards-flex">
          {vehicles.map((v, index) => (
            <div key={v.id} className="truck-card slide-up" style={{ animationDelay: `${index * 0.1}s` }}>
              <div className="cap-tag">{v.cap}</div>
              <img src={v.img} alt={v.name} />
              <h4>{v.name}</h4>
              <p>Starts at <strong>₹{v.price}</strong></p>
              <p>Base fare is inclusive of 1.0 km distance. </p>
              <button className="select-truck-btn">Select Vehicle</button>
            </div>
          ))}
        </div>
      </section>

      <section className="popular-routes">
        <div className="routes-container">
            <h3>Popular Routes from {selectedCity}</h3>
            <div className="routes-grid">
            {routes.map((route, i) => (
                <div key={i} className="route-card">
                <strong>to {route.to} ({route.kms})</strong>
                <p>Est. Fare: ₹{route.price}</p>
                </div>
            ))}
            </div>
        </div>
      </section>
    </div>
  );
};

export default BikePage;
